insert into publishers (name) values ('Murf.ai') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Murf', 'murf', p.id, 'AI voiceover studio with realistic text-to-speech voices.', 'Murf helps teams create voiceovers for videos, courses and ads using generative speech.', 'https://murf.ai', 'published', 'Freemium', 'Free trial / paid plans', true, false, false, ARRAY['tts', 'voiceover', 'studio']::text[], ARRAY['Business voiceover workflow']::text[], ARRAY['Naturalness varies by voice/language']::text[], ARRAY['Marketers', 'L&D']::text[], current_date from publishers p where p.name = 'Murf.ai' on conflict (slug) do nothing;
